CREATE OR REPLACE FUNCTION public.fn_audit_ajm1_changes() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_tenant uuid;v_actor uuid;v_record uuid;v_old jsonb;v_new jsonb;BEGIN v_old:=CASE WHEN TG_OP IN('UPDATE','DELETE') THEN to_jsonb(OLD) ELSE NULL END;v_new:=CASE WHEN TG_OP IN('INSERT','UPDATE') THEN to_jsonb(NEW) ELSE NULL END;v_record:=COALESCE((v_new->>'id')::uuid,(v_old->>'id')::uuid);v_tenant:=COALESCE(NULLIF(v_new->>'tenant_id','')::uuid,NULLIF(v_old->>'tenant_id','')::uuid);IF v_tenant IS NULL AND TG_TABLE_NAME='role_permissions' THEN SELECT tenant_id INTO v_tenant FROM public.roles WHERE id=COALESCE(NULLIF(v_new->>'role_id','')::uuid,NULLIF(v_old->>'role_id','')::uuid);END IF;IF v_tenant IS NULL AND TG_TABLE_NAME='permission_bundle_items' THEN SELECT tenant_id INTO v_tenant FROM public.permission_bundles WHERE id=COALESCE(NULLIF(v_new->>'bundle_id','')::uuid,NULLIF(v_old->>'bundle_id','')::uuid);END IF;IF v_tenant IS NULL AND TG_TABLE_NAME='role_template_permissions' THEN SELECT tenant_id INTO v_tenant FROM public.role_templates WHERE id=COALESCE(NULLIF(v_new->>'template_id','')::uuid,NULLIF(v_old->>'template_id','')::uuid);END IF;IF v_tenant IS NULL THEN IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;END IF;SELECT id INTO v_actor FROM public.clinic_users WHERE auth_user_id=auth.uid() LIMIT 1;INSERT INTO public.audit_trail(tenant_id,actor_id,actor_role,action,table_name,record_id,old_values,new_values) VALUES(v_tenant,v_actor,get_current_user_role(),TG_OP,TG_TABLE_NAME,v_record,v_old,v_new);IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;END; $$;
